function Get-UpgraderWingetOutdatedPackages {
        $wingetPath = Get-UpgraderCommandPath 'winget'
        if (-not $wingetPath) {
            return @()
        }

        $raw = (& $wingetPath upgrade --include-unknown --accept-source-agreements --disable-interactivity 2>&1 | Out-String)
        if ([string]::IsNullOrWhiteSpace($raw)) {
            return @()
        }

        $items = New-Object System.Collections.ArrayList
        $lines = $raw -split "`r?`n"
        $headerLine = $lines | Where-Object { $_ -match '^Name\s+Id\s+Version\s+Available\s+Source$' } | Select-Object -First 1
        if (-not $headerLine) {
            return @()
        }

        $idIndex = $headerLine.IndexOf('Id')
        $versionIndex = $headerLine.IndexOf('Version')
        $availableIndex = $headerLine.IndexOf('Available')
        $sourceIndex = $headerLine.IndexOf('Source')

        foreach ($line in $lines) {
            $trimmed = $line.Trim()
            if ([string]::IsNullOrWhiteSpace($trimmed)) { continue }
            if ($trimmed -match '[\u2580-\u259F]') { continue }
            if ($trimmed -match '^(Name|[-]{3,})') { continue }
            if ($trimmed -match '^(Upgrades available\.|No installed package found matching input criteria\.|The following packages have upgrades available:|(\d+) upgrades available\.)') { continue }
            if ($line.Length -lt $sourceIndex) { continue }

            $normalizedLine = $line.PadRight($sourceIndex + 16)

            [void]$items.Add([pscustomobject]@{
                Name = [string]$normalizedLine.Substring(0, $idIndex).Trim()
                Id = [string]$normalizedLine.Substring($idIndex, $versionIndex - $idIndex).Trim()
                Version = [string]$normalizedLine.Substring($versionIndex, $availableIndex - $versionIndex).Trim()
                Available = [string]$normalizedLine.Substring($availableIndex, $sourceIndex - $availableIndex).Trim()
                Source = [string]$normalizedLine.Substring($sourceIndex).Trim()
            })
        }

        return @($items)
    }

